function setHouseTheme(id){document.documentElement.style.setProperty('--house',house(id)?.color??'#648ed0');$('house-marker').style.background=house(id)?.color??'#648ed0';}
function closeModal(){if($('modal').open)$('modal').close();if(modalIsPause&&world){world.paused=modalRestorePause;modalIsPause=false;}canvas.focus({preventScroll:true});hudDirty=true;}
