$('modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
$('home').onclick=e=>{e.preventDefault();if(world&&currentScreen==='game')showOptions();else{showScreen('title');refreshContinue();}};
function chooseHouse(standalone=false){
  audio.activate();audio.click();
  const descriptions={1:'Noble Atreides. Loyalty, discipline, and the strength of Caladan.',0:'Ruthless Harkonnen. Heavy armor and overwhelming force.',2:'Cunning Ordos. Speed, deception, and the pursuit of profit.'};
  modal('Choose your House',`<p>The Emperor has opened Arrakis to competition. Which House will you command?</p><div class="house-choices">${[1,0,2].map(id=>`<button class="house-card" data-house="${id}" style="--house-color:${house(id)?.color}"><span class="crest">${id===1?'A':id===0?'H':'O'}</span><strong>${esc(house(id)?.name)}</strong><small>${descriptions[id]}</small></button>`).join('')}</div>`,[],false);
  document.querySelectorAll('[data-house]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.house);campaign=createCampaign(id);isStandalone=standalone;setHouseTheme(id);closeModal();if(standalone)showMissionPicker(id);else{storeCampaign(campaign);showCampaign();}});
}
function refreshContinue(){const saved=readCampaign();const good=content&&validateCampaign(saved,content);$('continue-game').hidden=!good;$('continue-game').textContent=good?`Continue House ${house(saved.house)?.name} · stage ${saved.stage+1}`:'Continue campaign';$('title-load').disabled=!content||!readSlots().some(Boolean);}
