function missionFacts(id){const m=content.scenarios.find(m=>m.id===id);const s=m?.sections??{};const human=Object.entries(s).find(([k,v])=>String(v.Brain??'').toLowerCase()==='human');return{mission:m,sections:s,human:human?.[1]??{},humanName:human?.[0]??house(campaign.house)?.name};}
