function centerBase(){if(!world)return;const base=world.entities.find(e=>e.house===world.house&&e.kind==='structure'&&e.type===8&&e.hp>0)??world.entities.find(e=>e.house===world.house&&e.hp>0);if(base){renderer.center(base.x/256,base.y/256);selection=[base.id];hudDirty=true;}}
