  const ck=JSON.stringify([catalogKind,Math.floor(h.credits),world.entities.filter(e=>e.house===world.house&&e.kind==='structure'&&e.hp>0).map(e=>e.type),prod.map(p=>[p.type,p.kind,p.ready])]);if(ck!==lastCatalogKey){lastCatalogKey=ck;renderCatalog();}
  const placement=targetMode==='place';$('target-banner').hidden=!targetMode;$('target-banner').textContent=placement?'Place completed structure · Left click to confirm · Esc to cancel':targetMode?`${targetMode.toUpperCase()} · Choose a target · Right click or Esc to cancel`:'';
