function showOptions(){
  if(!world)return;audio.click();modal('Options',`<div class="settings-grid"><label for="game-speed">Game speed <span id="speed-name"></span></label><input id="game-speed" type="range" min="0" max="4" value="${world.speed}" aria-label="Game speed"><label for="sound-on">Sound effects & speech</label><div class="switches"><input id="sound-on" type="checkbox" ${prefs.sound?'checked':''}><span>Enabled</span></div><label for="volume">Volume</label><input id="volume" type="range" min="0" max="100" value="${prefs.volume*100}" aria-label="Volume"><label for="edge-scroll">Edge scrolling</label><div class="switches"><input id="edge-scroll" type="checkbox" ${prefs.edgeScroll?'checked':''}><span>Enabled</span></div></div><p>The battlefield is paused while this terminal is open.</p><div class="title-actions" style="margin-bottom:0"><button id="save-action">Save game</button><button id="load-action">Load game</button><button id="restart-action">Restart mission</button><button id="return-menu">Return to main menu</button></div>`,[{label:'Resume game',primary:true,run:closeModal}]);
  const names=['Slowest','Slow','Normal','Fast','Fastest'];$('speed-name').textContent=`· ${names[world.speed]}`;$('game-speed').oninput=()=>{world.speed=Number($('game-speed').value);prefs.speed=world.speed;$('speed-name').textContent=`· ${names[world.speed]}`;storePreferences(prefs);};$('sound-on').onchange=()=>{prefs.sound=$('sound-on').checked;storePreferences(prefs);};$('volume').oninput=()=>{prefs.volume=Number($('volume').value)/100;storePreferences(prefs);};$('edge-scroll').onchange=()=>{prefs.edgeScroll=$('edge-scroll').checked;storePreferences(prefs);};$('save-action').onclick=()=>showSaves('save');$('load-action').onclick=()=>showSaves('load');$('restart-action').onclick=()=>modal('Restart this operation?',`<p>Your current battlefield state will be discarded. Saved games remain available.</p>`,[{label:'Cancel',run:showOptions},{label:'Restart mission',primary:true,run:()=>startMission(world.scenarioId)}]);$('return-menu').onclick=()=>modal('Return to the main menu?',`<p>Your campaign progress is saved. Save this mission first to preserve its battlefield state.</p>`,[{label:'Keep playing',run:showOptions},{label:'Main menu',primary:true,run:()=>{closeModal();world.paused=true;showScreen('title');refreshContinue();}}]);
}
function showSaves(mode='load'){
  const slots=readSlots();modal(mode==='save'?'Save game':'Load game',`${mode==='save'?`<label for="save-name" class="eyebrow">SAVE DESCRIPTION</label><input id="save-name" class="save-name" maxlength="48" value="${esc(`${house(world.house)?.name} · ${world.scenarioId.replace('.INI','')} · ${time(world.tick)}`)}">`:''}<div class="save-list">${slots.map((s,i)=>`<div class="save-slot"><span class="slot-id">${String(i+1).padStart(2,'0')}</span><div class="slot-copy"><strong>${esc(s?.name??'Empty slot')}</strong><p>${s?`${esc(s.world?.scenarioId??'')} · ${time(s.world?.tick??0)} · ${esc(new Date(s.savedAt).toLocaleDateString())}`:'No saved transmission'}</p></div><button data-slot="${i}" ${mode==='load'&&!s?'disabled':''}>${mode==='save'?'Save':'Load'}</button>${s?`<button class="delete" data-delete="${i}" aria-label="Delete save ${i+1}">×</button>`:''}</div>`).join('')}</div><div class="toast" id="save-feedback" role="status"></div>`,[{label:world&&currentScreen==='game'?'Back to options':'Back',run:world&&currentScreen==='game'?showOptions:closeModal}]);
  document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.slot);try{if(mode==='save'){const snapshot=structuredClone(world);snapshot.paused=modalRestorePause;writeSlot(i,snapshot,{selection,camera:renderer.camera,isStandalone},campaign,$('save-name').value);audio.click();showSaves('save');$('save-feedback').textContent=`Saved to slot ${i+1}.`;refreshContinue();}else{const s=loadSlot(i,Engine.validateSave,content);if(!validateCampaign(s.campaign,content))throw new Error('The campaign data in this save is invalid.');closeModal();world=s.world;campaign=s.campaign;selection=Array.isArray(s.ui?.selection)?s.ui.selection.filter(id=>world.entities.some(e=>e.id===id)):[];renderer.camera={x:Math.max(0,Math.min(49,Number(s.ui?.camera?.x)||0)),y:Math.max(0,Math.min(54,Number(s.ui?.camera?.y)||0))};isStandalone=!!s.ui?.isStandalone;setHouseTheme(world.house);resultShown=false;targetMode=null;lastEventId=world.events.at(-1)?.id??0;showScreen('game');$('mission-name').textContent=`House ${house(world.house)?.name} · ${world.scenarioId.replace('.INI','')}`;$('field-label').textContent=`${house(world.house)?.name} tactical command`;resetUIKeys();setNotice(`Loaded ${s.name}.`);accumulator=0;}}catch(e){$('save-feedback').textContent=e.message;}});
  document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{try{deleteSlot(Number(b.dataset.delete));showSaves(mode);refreshContinue();}catch(e){$('save-feedback').textContent=e.message;}});
}
function showMentat(){
  if(!world)return;modal('Mentat',`<div class="briefing-layout"><div class="advisor-portrait" id="advisor-portrait"></div><div class="briefing-text"><p class="eyebrow">HOUSE ${esc(house(world.house)?.name).toUpperCase()}</p><h3>Situation report.</h3><p>${esc(originalText(world.scenarioId,3)||briefingText(world.scenarioId))}</p><p>Select a structure to repair or sell it. Build a refinery to receive a harvester. Return a loaded harvester to the refinery to bank its spice.</p><div class="briefing-facts"><span>${world.entities.filter(e=>e.house===world.house&&e.kind==='unit'&&e.hp>0).length} UNITS</span><span>${world.entities.filter(e=>e.house===world.house&&e.kind==='structure'&&e.hp>0).length} STRUCTURES</span></div></div></div>`,[{label:'Controls',run:showHelp},{label:'Return to battlefield',primary:true,run:closeModal}]);drawAdvisor($('advisor-portrait'),world.house);
}
function showResults(){
  resultShown=true;const won=world.outcome==='victory';const score=Math.round(world.result?.score??world.score??Math.max(0,playerHouse().credits/100));if(won&&!isStandalone){campaign=completeMission(campaign,world.scenarioId,content,{score});storeCampaign(campaign);}audio.sample(won?'victory':'defeat',world.house);
  modal(won?'Mission accomplished':'Mission failed',`<div class="result-banner ${won?'':'defeat'}"><p class="eyebrow">HOUSE ${esc(house(world.house)?.name).toUpperCase()}</p><h3>${won?'Victory.':'Defeat.'}</h3><p>${esc(originalText(world.scenarioId,won?1:2)||(won?'Your orders have been fulfilled. The spice flows in your House’s favor.':'Your foothold on Arrakis has been lost. Regroup and try again.'))}</p></div><div class="result-grid"><div><span>Mission time</span><strong>${time(world.tick)}</strong></div><div><span>Score</span><strong>${score.toLocaleString()}</strong></div><div><span>Credits</span><strong>${Math.floor(playerHouse().credits).toLocaleString()}</strong></div></div>`,[{label:'Review battlefield',run:closeModal},{label:won&&!isStandalone?(campaign.finished?'Campaign results':'Next operation'):'Retry mission',primary:true,run:()=>{closeModal();if(won&&!isStandalone)showCampaign();else startMission(world.scenarioId);}}],false);
}
function showHelp(){modal('Field manual',`<p>Secure spice, build your base, and fulfill the mission objective. Your refinery automatically receives a harvester when completed.</p><div class="help-grid"><div><kbd>Left click</kbd> Select a unit or structure.<br><kbd>Drag</kbd> Select a group of your units.<br><kbd>Shift + click</kbd> Add or remove a unit.</div><div><kbd>Right click</kbd> Move, attack an enemy, or harvest spice.<br><kbd>A</kbd> Target an attack.<br><kbd>G</kbd> Target a spice field.</div><div><kbd>Arrow keys</kbd> Pan the viewport.<br><kbd>Minimap</kbd> Reposition the camera.<br><kbd>H</kbd> Center on your base.</div><div><kbd>Tab</kbd> Cycle your units.<br><kbd>S</kbd> Stop.<br><kbd>R</kbd> Return spice to refinery.</div><div><kbd>Space</kbd> Pause / resume.<br><kbd>Esc</kbd> Cancel targeting / open Options.<br><kbd>F1</kbd> Consult your Mentat.</div><div>Build structures in Production, then place the completed building on rock near your base. Windtraps supply power. Silos store spice revenue.</div></div><details class="notes"><summary>About this reconstruction</summary><p>The graphics, object prices and hitpoints, mission placements, campaign choices and resource files come from the supplied game. Recovered integer speed scaling, nominal 60 Hz clocks, harvesting constants and objective timing are implemented. Terrain generation, route choices, parts of combat, construction pacing and AI are reconstructed approximations. Music synthesis, full original EMC callback behavior and original DOS save-file compatibility remain incomplete. Browser saves preserve the reconstructed simulation. This is a playable reconstruction, not a verified bit-exact port.</p></details>`,[{label:'Understood',primary:true,run:closeModal}]);}

canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(!world||$('modal').open)return;audio.activate();canvas.focus({preventScroll:true});const p=renderer.point(e.clientX,e.clientY);pointer=p;const mini=renderer.minimapPoint(p);if(mini){renderer.center(mini.x,mini.y);dragStart={mini:true};canvas.setPointerCapture(e.pointerId);return;}if(p.y<18&&e.button===0){if(p.x<97)showMentat();else if(p.x<185)showOptions();return;}if(e.button===2){const tile=renderer.worldPoint(p);if(tile){if(targetMode==='place'){targetMode=null;hudDirty=true;}else issueAt(tile,true);}return;}const tile=renderer.worldPoint(p);if(!tile)return;if(targetMode){issueAt(tile);return;}dragStart={x:p.x,y:p.y,shift:e.shiftKey,pointerId:e.pointerId};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{const p=renderer.point(e.clientX,e.clientY);pointer=p;renderer.hover=renderer.worldPoint(p);if(renderer.hover)$('coordinates').textContent=`${String(renderer.hover.x).padStart(2,'0')} E · ${String(renderer.hover.y).padStart(2,'0')} S`;
  if(dragStart?.mini){const mini=renderer.minimapPoint(p);if(mini)renderer.center(mini.x,mini.y);return;}
  if(dragStart&&Math.abs(p.x-dragStart.x)+Math.abs(p.y-dragStart.y)>4)renderer.drag={x:Math.max(0,Math.min(p.x,dragStart.x)),y:Math.max(40,Math.min(p.y,dragStart.y)),w:Math.abs(p.x-dragStart.x),h:Math.abs(p.y-dragStart.y)};
});
canvas.addEventListener('pointerup',e=>{if(!dragStart||dragStart.mini){dragStart=null;return;}const p=renderer.point(e.clientX,e.clientY);if(renderer.drag){const r=renderer.drag;const ids=world.entities.filter(e=>e.house===world.house&&e.kind==='unit'&&e.hp>0).filter(e=>{const x=(e.x/256-renderer.camera.x)*16,y=40+(e.y/256-renderer.camera.y)*16;return x>=r.x&&x<=r.x+r.w&&y>=r.y&&y<=r.y+r.h;}).map(e=>e.id);selection=dragStart.shift?[...new Set([...selection,...ids])]:ids;resetUIKeys();audio.click();}else{const tile=renderer.worldPoint(p),e=tile&&renderer.entityAt(world,tile);if(e)selectEntity(e,dragStart.shift);else if(!dragStart.shift){selection=[];resetUIKeys();}}renderer.drag=null;dragStart=null;});
canvas.addEventListener('pointerleave',()=>{if(!dragStart)pointer=null;renderer.hover=null;});
canvas.addEventListener('wheel',e=>{e.preventDefault();renderer.pan(e.shiftKey?Math.sign(e.deltaY)*2:0,e.shiftKey?0:Math.sign(e.deltaY)*2);},{passive:false});
document.addEventListener('keydown',e=>{
  if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;
  if($('modal').open)return;
  keys.add(e.key);if(currentScreen!=='game'||!world)return;
  if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Tab','F1'].includes(e.key))e.preventDefault();
  if(e.repeat&&!e.key.startsWith('Arrow'))return;
  switch(e.key.toLowerCase()){
    case 'escape':if(targetMode){targetMode=null;hudDirty=true;}else showOptions();break;
    case ' ':togglePause();break;
    case 'f1':showMentat();break;
    case 'h':centerBase();break;
    case 'a':if(e.target===canvas)setTarget('attack');break;
    case 'g':setTarget('harvest');break;
    case 'm':setTarget('move');break;
    case 's':command({type:'stop',ids:ownUnits().map(e=>e.id)});break;
    case 'r':command({type:'return',ids:ownUnits().map(e=>e.id)});break;
    case 'd':if(ownUnits().some(e=>e.type===17))command({type:'deploy',ids:ownUnits().map(e=>e.id)});break;
    case 'tab':{const units=world.entities.filter(e=>e.house===world.house&&e.kind==='unit'&&e.hp>0);if(units.length){const index=units.findIndex(e=>e.id===selection[0]);const next=units[(index+(e.shiftKey?units.length-1:1))%units.length];selection=[next.id];renderer.center(next.x/256,next.y/256);resetUIKeys();}break;}
  }
});
document.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>{keys.clear();pointer=null;});document.addEventListener('visibilitychange',()=>{if(document.hidden){lastFrame=0;accumulator=0;keys.clear();}});window.addEventListener('resize',()=>{if(currentScreen==='campaign')drawCampaign();});
$('new-game').onclick=()=>chooseHouse(false);$('continue-game').onclick=()=>{audio.activate();campaign=readCampaign();if(validateCampaign(campaign,content))showCampaign();else chooseHouse(false);};$('mission-select').onclick=()=>{audio.activate();showMissionPicker();};$('title-load').onclick=()=>{audio.activate();showSaves('load');};$('options-button').onclick=showOptions;$('mentat-button').onclick=showMentat;$('help-button').onclick=()=>{audio?.activate();showHelp();};$('pause-toggle').onclick=togglePause;$('center-base').onclick=centerBase;$('campaign-back').onclick=()=>{showScreen('title');refreshContinue();};$('deploy-button').onclick=()=>showBriefing(chosenMission);$('structures-tab').onclick=()=>{catalogKind='structure';lastCatalogKey='';hudDirty=true;};$('units-tab').onclick=()=>{catalogKind='unit';lastCatalogKey='';hudDirty=true;};$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.querySelector('.field').requestFullscreen?.();};

function frame(now){
  const delta=lastFrame?Math.min(.25,(now-lastFrame)/1000):0;lastFrame=now;
  if(world&&currentScreen==='game'){
    accumulator+=delta*60;const steps=Math.min(30,Math.floor(accumulator));if(steps){Engine.tickGame(world,content,steps);accumulator-=steps;}
    if(now-lastPan>90&&!$('modal').open){let dx=(keys.has('ArrowRight')?1:0)-(keys.has('ArrowLeft')?1:0),dy=(keys.has('ArrowDown')?1:0)-(keys.has('ArrowUp')?1:0);if(prefs.edgeScroll&&pointer&&!dragStart&&pointer.y>=40&&pointer.x<240){if(pointer.x<3)dx--;if(pointer.x>237)dx++;if(pointer.y<43)dy--;if(pointer.y>197)dy++;}if(dx||dy)renderer.pan(dx,dy);lastPan=now;}
    const ready=targetMode==='place'?world.production.find(p=>p.house===world.house&&p.kind==='structure'&&p.ready):null;let placement=ready?{type:ready.type,valid:true}:null;
    if(placement&&renderer.hover&&Engine.canPlace){const result=Engine.canPlace(world,content,ready.type,renderer.hover.x+renderer.hover.y*64);placement.valid=typeof result==='boolean'?result:result.ok;}
    renderer.draw(world,{selected:selection,mode:targetMode,placement,message:now<noticeUntil?notice:''});
    if(hudDirty||now-lastHUD>150){updateHUD();lastHUD=now;}
    if(world.outcome&&!resultShown)showResults();
  }
  requestAnimationFrame(frame);
}
async function boot(){
  const response=await fetch('assets/content.json');if(!response.ok)throw new Error(`Game content could not be loaded (${response.status}).`);content=await response.json();configurePersistence(content,Engine.validateSave);renderer=new Renderer(canvas,content);audio=new AudioController(content,prefs);await renderer.load();
  const title=renderer.image('title'),planet=renderer.image('planet');if(title){$('title-image').src=content.graphics.images.title;$('title-image').hidden=false;$('title-image').style.objectFit='contain';$('title-image').style.objectPosition='center 12%';$('title-image').style.height='55%';}if(planet)document.querySelector('.title-visual').style.backgroundImage=`linear-gradient(0deg,#0f100bd9,transparent 75%),url('${content.graphics.images.planet}')`;
  document.querySelector('.title-visual').style.backgroundSize='cover';document.querySelector('.title-visual').style.backgroundPosition='center';$('loading-text').textContent='Three Great Houses. One desert world. The struggle for spice begins here.';$('terminal-status').textContent='ARRAKIS UPLINK ESTABLISHED';$('new-game').disabled=false;$('mission-select').disabled=false;refreshContinue();campaign=createCampaign(1);requestAnimationFrame(frame);
  window.dune={get world(){return world;},get content(){return content;},get campaign(){return campaign;},get renderer(){return renderer;},command,select(ids){selection=ids;resetUIKeys();},start(id='SCENA001.INI',houseId=1){campaign=createCampaign(houseId);isStandalone=true;startMission(id);},advance(ticks){Engine.tickGame(world,content,ticks);hudDirty=true;},snapshot(){return structuredClone(world);}};
}
boot().catch(error=>{console.error(error);$('fatal-message').textContent=error.message;$('fatal').hidden=false;$('loading-text').textContent='Connection failed. Reload to try again.';});
